// ============================================================
// ERROR HANDLER: Parse and Format Error (v3.0)
// ============================================================

const error = $json;
const execution = error.execution || {};
const workflow = error.workflow || {};

// Извлекаем информацию об ошибке
const errorMessage = execution.error?.message || 'Unknown error';
const errorStack = execution.error?.stack || '';
const nodeName = execution.lastNodeExecuted || 'Unknown node';
const workflowName = workflow.name || 'Unknown workflow';
const workflowId = workflow.id || 'Unknown';
const executionId = execution.id || 'Unknown';
const timestamp = new Date().toISOString();

// Определяем severity
let severity = 'WARNING';
if (errorMessage.includes('FATAL') || errorMessage.includes('crash')) {
  severity = 'CRITICAL';
} else if (errorMessage.includes('timeout') || errorMessage.includes('rate limit')) {
  severity = 'INFO';
}

// Форматируем для логирования
const logEntry = {
  timestamp: timestamp,
  severity: severity,
  workflow_name: workflowName,
  workflow_id: workflowId,
  execution_id: executionId,
  node_name: nodeName,
  error_message: errorMessage,
  error_stack: errorStack.substring(0, 500),
  raw_data: JSON.stringify(error).substring(0, 1000)
};

// Форматируем сообщение для Telegram
const telegramMessage = `🚨 <b>${severity}: Ошибка в HR Bot</b>\n\n` +
  `📋 Workflow: ${workflowName}\n` +
  `🔧 Node: ${nodeName}\n` +
  `❌ Error: ${errorMessage.substring(0, 200)}\n\n` +
  `🕐 Time: ${timestamp}\n` +
  `🆔 Execution: ${executionId}`;

return {
  ...logEntry,
  telegram_message: telegramMessage
};

// Log non-critical error (just console for now)
console.log('⚠️ Non-critical error logged:', $json.error_message);
return $json;
